package vn.com.apartment.billing;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.LocalDateTime;
@Entity @Table(name="bank_transactions") public class BankTransaction{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(nullable=false,length=30) private String provider;@Column(name="provider_transaction_id",nullable=false,length=100) private String providerTransactionId;@Column(name="credit_account",length=50) private String creditAccount;@Column(nullable=false,precision=18,scale=2) private BigDecimal amount;@Column(length=500) private String description;@Column(name="transaction_time",nullable=false) private LocalDateTime transactionTime;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="matched_qr_request_id") private PaymentQrRequest matchedQrRequest;@Column(name="match_status",nullable=false,length=30) private String matchStatus;@Column(name="raw_payload",length=4000) private String rawPayload;@Column(name="created_at",nullable=false) private LocalDateTime createdAt=LocalDateTime.now();protected BankTransaction(){}public BankTransaction(String provider,String transactionId,String account,BigDecimal amount,String description,LocalDateTime time,PaymentQrRequest qr,String status,String raw){this.provider=provider;providerTransactionId=transactionId;creditAccount=account;this.amount=amount;this.description=description;transactionTime=time;matchedQrRequest=qr;matchStatus=status;rawPayload=raw;}public Long getId(){return id;}public String getMatchStatus(){return matchStatus;}
}
